create or replace view public.dd_company_owner_attention_v1 with (security_invoker = true) as select id,priority,domain,reason,recommended_action,source_table,source_record_id,metadata,created_at,metadata->'governor'->>'state' as governor_state,(metadata->'governor'->>'rank_score')::numeric as rank_score,coalesce((metadata->'governor'->>'needs_owner_now')::boolean,true) as needs_owner_now,(metadata->'governor_rank'->>'position')::int as rank_position,metadata->'governor'->>'next_action' as governor_next_action,metadata->'governor'->'reasons' as rank_reasons,(metadata->'governor'->>'wake_at')::timestamptz as wake_at from public.dd_owner_attention_queue where status='OPEN' order by coalesce((metadata->'governor'->>'needs_owner_now')::boolean,true) desc,coalesce((metadata->'governor'->>'rank_score')::numeric,0) desc,case upper(coalesce(priority,'')) when 'P0' then 1 when 'URGENT' then 1 when 'CRITICAL' then 1 when 'P1' then 2 when 'HIGH' then 2 when 'P2' then 3 when 'MEDIUM' then 3 else 4 end,created_at,id;
